// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// List notification channels
	// (GET /v1/projects/{project_id}/alert-channels)
	ListAlertChannels(ctx context.Context, request ListAlertChannelsRequestObject) (ListAlertChannelsResponseObject, error)
	// Add a notification channel
	// (POST /v1/projects/{project_id}/alert-channels)
	CreateAlertChannel(ctx context.Context, request CreateAlertChannelRequestObject) (CreateAlertChannelResponseObject, error)
	// Delete a channel and remove it from rules
	// (DELETE /v1/projects/{project_id}/alert-channels/{channel_id})
	DeleteAlertChannel(ctx context.Context, request DeleteAlertChannelRequestObject) (DeleteAlertChannelResponseObject, error)
	// Send a test notification
	// (POST /v1/projects/{project_id}/alert-channels/{channel_id}/test)
	TestAlertChannel(ctx context.Context, request TestAlertChannelRequestObject) (TestAlertChannelResponseObject, error)
	// List alert rules with their current state
	// (GET /v1/projects/{project_id}/alerts)
	ListAlerts(ctx context.Context, request ListAlertsRequestObject) (ListAlertsResponseObject, error)
	// Create an alert rule
	// (POST /v1/projects/{project_id}/alerts)
	CreateAlert(ctx context.Context, request CreateAlertRequestObject) (CreateAlertResponseObject, error)
	// Chart a rule's metric against its threshold
	// (POST /v1/projects/{project_id}/alerts/preview)
	PreviewAlert(ctx context.Context, request PreviewAlertRequestObject) (PreviewAlertResponseObject, error)
	// Delete a rule and its history
	// (DELETE /v1/projects/{project_id}/alerts/{alert_id})
	DeleteAlert(ctx context.Context, request DeleteAlertRequestObject) (DeleteAlertResponseObject, error)
	// Get a rule with its recent history
	// (GET /v1/projects/{project_id}/alerts/{alert_id})
	GetAlert(ctx context.Context, request GetAlertRequestObject) (GetAlertResponseObject, error)
	// Update a rule
	// (PUT /v1/projects/{project_id}/alerts/{alert_id})
	UpdateAlert(ctx context.Context, request UpdateAlertRequestObject) (UpdateAlertResponseObject, error)
	// Mute or unmute a rule's notifications
	// (POST /v1/projects/{project_id}/alerts/{alert_id}/mute)
	MuteAlert(ctx context.Context, request MuteAlertRequestObject) (MuteAlertResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

